from pathlib import Path
import hashlib,json,os,tempfile,fcntl,time
root=Path('/var/www/html/perf/kvc-tcp-20261020')
lock=Path('/tmp/kvc-yche-publish.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX)
old=(root/'SHA256SUMS').read_bytes(); sha=lambda b:hashlib.sha256(b).hexdigest()
entries={n:h for h,n in (line.split('  ',1) for line in old.decode().splitlines())}
add={}
for key,text in records.items():
 p=root/'builds'/(key+'.json'); assert not p.exists()
 add[p]=text.encode()
history=root/'build-appendix/link-repair'/sha(old)/'SHA256SUMS'; assert not history.exists();add[history]=old
receipt=root/'build-appendix/build-record-links.json'; assert not receipt.exists()
add[receipt]=(json.dumps({'kind':'restore_missing_historical_build_record_links','source':'Byte-identical fixed build records from kvc-batch-tcp-20261020/builds','prior_manifest_sha256':sha(old),'records':{k:sha(v.encode()) for k,v in records.items()},'native_benchmark_rerun':False},indent=2)+'\n').encode()
for p,v in add.items():entries[str(p.relative_to(root))]=sha(v)
add[root/'SHA256SUMS']=''.join(h+'  '+n+'\n' for n,h in sorted(entries.items())).encode()
def write(p,v):
 p.parent.mkdir(parents=True,exist_ok=True)
 fd,tmp=tempfile.mkstemp(prefix='.appendix-link-',dir=p.parent)
 with os.fdopen(fd,'wb') as f:f.write(v);f.flush();os.fsync(f.fileno())
 os.chmod(tmp,0o644);os.replace(tmp,p)
written=[]
try:
 for p,v in add.items():
  if p.name=='SHA256SUMS' and p.parent==root:assert p.read_bytes()==old
  write(p,v);written.append(p)
except BaseException:
 for p in reversed(written):
  if p.parent==root:write(p,old)
  else:p.unlink()
 raise
print(json.dumps({'passed':True,'added_build_records':{k:sha(v.encode()) for k,v in records.items()},'manifest_entries':len(entries)}))
